package main

const startupPageHTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Athena Startup Center</title>
<style>
:root{--ink:#10251f;--muted:#66766f;--paper:#f8f4e9;--card:rgba(255,255,255,.82);--line:#d9e4da;--green:#087f5b;--mint:#a7f3d0;--red:#c2413b;--amber:#d97706;--navy:#102238}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--ink);font-family:"Avenir Next","Segoe UI",sans-serif;background:radial-gradient(circle at 12% 8%,rgba(167,243,208,.7),transparent 30%),radial-gradient(circle at 90% 90%,rgba(252,211,77,.28),transparent 32%),var(--paper)}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.32;background-image:linear-gradient(rgba(16,37,31,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(16,37,31,.04) 1px,transparent 1px);background-size:28px 28px}.shell{width:min(1180px,calc(100% - 40px));margin:0 auto;padding:36px 0 48px}.masthead{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.brand{display:flex;align-items:center;gap:14px}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:16px;color:white;background:var(--navy);box-shadow:0 12px 30px rgba(16,34,56,.22)}.mark svg{width:29px}.brand h1{font-size:21px;letter-spacing:-.02em;margin:0}.brand p{margin:3px 0 0;color:var(--muted);font-size:13px}.version{font:600 12px ui-monospace,SFMono-Regular,monospace;padding:8px 11px;border:1px solid var(--line);border-radius:999px;background:rgba(255,255,255,.65)}.hero{position:relative;overflow:hidden;padding:32px;border:1px solid rgba(8,127,91,.24);border-radius:28px;background:var(--card);box-shadow:0 24px 70px rgba(38,70,57,.13);backdrop-filter:blur(18px)}.hero:after{content:"ATHENA";position:absolute;right:-10px;top:-28px;font-size:112px;font-weight:900;letter-spacing:-.08em;color:rgba(8,127,91,.04);pointer-events:none}.status-row{position:relative;display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:28px}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:11px;font-weight:800;color:var(--green);margin-bottom:8px}.headline{font-size:clamp(28px,4vw,48px);line-height:1.04;letter-spacing:-.045em;margin:0;max-width:680px}.subline{margin:12px 0 0;color:var(--muted);font-size:15px}.pulse{width:68px;height:68px;flex:0 0 auto;display:grid;place-items:center;border-radius:22px;background:#e5f8ee;color:var(--green);position:relative}.pulse:before{content:"";position:absolute;inset:10px;border:2px solid currentColor;border-radius:50%;animation:ring 1.5s ease-out infinite}.pulse.ready{background:#d9fbe9}.pulse.error{background:#fee8e6;color:var(--red)}.pulse.error:before{animation:none;border-radius:8px}.pulse svg{width:30px;position:relative}@keyframes ring{0%{transform:scale(.6);opacity:1}100%{transform:scale(1.3);opacity:0}}.progress-track{height:7px;background:#e7ece7;border-radius:999px;overflow:hidden;margin-bottom:28px}.progress-bar{height:100%;width:0;background:linear-gradient(90deg,var(--green),#20b486);border-radius:999px;transition:width .5s ease}.grid{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(380px,.95fr);gap:22px}.panel{border:1px solid var(--line);border-radius:20px;background:rgba(255,255,255,.62);overflow:hidden}.panel-title{display:flex;align-items:center;justify-content:space-between;padding:16px 18px;border-bottom:1px solid var(--line);font-size:13px;font-weight:800}.count{color:var(--muted);font-weight:600}.steps{padding:7px 18px}.step{display:grid;grid-template-columns:28px 1fr auto;gap:12px;align-items:center;padding:11px 0;border-bottom:1px solid rgba(217,228,218,.7)}.step:last-child{border:0}.dot{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;border:1.5px solid #c9d3cc;color:#87958e;font-size:12px;font-weight:900}.step.running .dot{border-color:var(--green);color:var(--green);box-shadow:0 0 0 5px rgba(8,127,91,.08)}.step.complete .dot{background:var(--green);border-color:var(--green);color:white}.step.error .dot{background:var(--red);border-color:var(--red);color:white}.step-name{font-size:13px;font-weight:750}.step-detail{font-size:11px;color:var(--muted);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:390px}.step-state{font:700 10px ui-monospace,SFMono-Regular,monospace;text-transform:uppercase;color:#8b9891}.step.running .step-state{color:var(--green)}.step.error .step-state{color:var(--red)}.terminal{background:var(--navy);color:#d9e6e2;min-height:408px}.terminal .panel-title{border-color:rgba(255,255,255,.1);color:white}.tabs{display:flex;gap:4px;overflow:auto}.tab{border:0;background:transparent;color:#8fa6a0;padding:5px 8px;border-radius:7px;cursor:pointer;font:700 10px ui-monospace,SFMono-Regular,monospace}.tab.active{background:rgba(167,243,208,.14);color:var(--mint)}pre{height:350px;margin:0;padding:16px 18px;overflow:auto;white-space:pre-wrap;word-break:break-word;font:11px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace;color:#b9cbc6}.error-box{display:none;margin-top:20px;padding:18px;border:1px solid rgba(194,65,59,.28);border-radius:18px;background:#fff4f2}.error-box.show{display:block}.error-title{font-weight:850;color:var(--red);margin-bottom:7px}.error-text{font:12px/1.55 ui-monospace,SFMono-Regular,monospace;white-space:pre-wrap}.actions{display:flex;gap:10px;margin-top:15px}.button{border:0;border-radius:12px;padding:11px 15px;font-weight:800;cursor:pointer}.button.primary{background:var(--green);color:white}.button.secondary{background:white;color:var(--ink);border:1px solid var(--line)}.ready-actions{display:none;margin-top:20px;align-items:center;gap:12px}.ready-actions.show{display:flex}.ready-note{font-size:13px;color:var(--muted)}@media(max-width:850px){.shell{width:min(100% - 22px,680px);padding-top:18px}.hero{padding:22px}.grid{grid-template-columns:1fr}.terminal{min-height:330px}pre{height:275px}.status-row{gap:12px}.pulse{width:54px;height:54px;border-radius:17px}.step-detail{max-width:220px}}@media(max-width:520px){.masthead{align-items:flex-start}.version{display:none}.hero:after{display:none}.headline{font-size:30px}.status-row{margin-bottom:20px}.step{grid-template-columns:25px 1fr}.step-state{display:none}.step-detail{max-width:240px}.tabs{max-width:220px}}
</style>
<style>
.update-box{display:none;margin:0 0 22px;padding:20px;border:1px solid rgba(217,119,6,.32);border-radius:20px;background:linear-gradient(135deg,#fffaf0,#fff7df)}.update-box.show{display:block}.update-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.update-kicker{color:var(--amber);font-size:11px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.update-title{margin:5px 0 0;font-size:20px;letter-spacing:-.025em}.update-message{margin:7px 0 0;color:var(--muted);font-size:13px}.update-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:9px;margin-top:16px}.update-item{padding:12px 14px;border:1px solid rgba(217,119,6,.18);border-radius:13px;background:rgba(255,255,255,.75)}.update-name{font-size:13px;font-weight:850}.update-hash{margin-top:5px;color:#8d6b36;font:10px ui-monospace,SFMono-Regular,monospace}.button:disabled{cursor:wait;opacity:.6}@media(max-width:520px){.update-head{display:block}.update-list{grid-template-columns:1fr}}
</style>
</head>
<body>
<main class="shell">
  <header class="masthead"><div class="brand"><div class="mark"><svg viewBox="0 0 32 32" fill="none"><path d="M16 3 27 9v14l-11 6L5 23V9l11-6Z" stroke="currentColor" stroke-width="2.2"/><path d="m10 12 6-3 6 3v7l-6 4-6-4v-7Z" stroke="currentColor" stroke-width="2.2"/><path d="M16 9v14M10 12l6 4 6-4" stroke="currentColor" stroke-width="2.2"/></svg></div><div><h1>Athena</h1><p id="brand-subtitle">Startup Center / 启动中心</p></div></div><div class="version" id="version">v...</div></header>
  <section class="hero">
    <div class="status-row"><div><div class="eyebrow" id="eyebrow">SYSTEM STARTUP</div><h2 class="headline" id="headline">Preparing your agent workspace</h2><p class="subline" id="message">Connecting the pieces. This may take a few minutes on first launch.</p></div><div class="pulse" id="pulse"><svg viewBox="0 0 24 24" fill="none"><path d="M12 3v4m0 10v4M3 12h4m10 0h4M5.64 5.64l2.83 2.83m7.06 7.06 2.83 2.83m0-12.72-2.83 2.83m-7.06 7.06-2.83 2.83" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></div></div>
    <div class="progress-track"><div class="progress-bar" id="progress"></div></div>
    <div class="update-box" id="update-box"><div class="update-head"><div><div class="update-kicker" id="update-kicker">PACKAGE UPDATE</div><h3 class="update-title" id="update-title">New service packages are available</h3><p class="update-message" id="update-message"></p></div></div><div class="update-list" id="update-list"></div><div class="actions"><button class="button primary" id="update-apply">Update and restart</button><button class="button secondary" id="update-dismiss">Not now</button></div></div>
    <div class="grid">
      <section class="panel"><div class="panel-title"><span id="steps-title">STARTUP SEQUENCE</span><span class="count" id="count">0 / 9</span></div><div class="steps" id="steps"></div></section>
      <section class="panel terminal"><div class="panel-title"><span id="logs-title">LIVE LOG</span><div class="tabs"><button class="tab active" data-log="launcher">launcher</button><button class="tab" data-log="postgres">postgres</button><button class="tab" data-log="runtime">runtime</button><button class="tab" data-log="client">client</button></div></div><pre id="log">Waiting for startup output...</pre></section>
    </div>
    <div class="error-box" id="error-box"><div class="error-title" id="error-title">Startup stopped at an error</div><div class="error-text" id="error-text"></div><div class="actions"><button class="button primary" id="retry">Retry startup</button><button class="button secondary" id="copy">Copy error</button></div></div>
    <div class="ready-actions" id="ready-actions"><button class="button primary" id="open-athena">Open Athena</button><span class="ready-note" id="ready-note">Opening automatically in 5 seconds...</span><button class="button secondary" id="stay">Stay here</button></div>
  </section>
</main>
<script>
const zh=(navigator.language||'').toLowerCase().startsWith('zh');
const text=zh?{headline:'正在准备你的 Agent 工作空间',starting:'正在连接各项服务，首次启动可能需要几分钟。',ready:'Athena 已准备完成',readyMsg:'所有服务运行正常。',error:'启动遇到问题',errorTitle:'启动在此处停止',steps:'启动步骤',logs:'实时日志',retry:'重试启动',retrying:'正在重新启动...',copy:'复制错误',open:'进入 Athena',stay:'留在这里',opening:'将在 {n} 秒后自动进入...',states:{pending:'等待',running:'执行中',complete:'完成',error:'错误'},labels:{manifest:'读取发布清单','database-package':'准备 PostgreSQL','services-package':'下载运行服务','frontend-package':'准备前端界面',configuration:'生成服务配置',database:'启动 PostgreSQL','agent-runtime':'启动 Agent Runtime','agent-runtime-client':'启动 Runtime Client',frontend:'启动 Athena 界面'}}:{headline:'Preparing your agent workspace',starting:'Connecting the pieces. First launch may take a few minutes.',ready:'Athena is ready',readyMsg:'Every service is healthy and ready.',error:'Startup needs attention',errorTitle:'Startup stopped at an error',steps:'Startup sequence',logs:'Live log',retry:'Retry startup',retrying:'Restarting...',copy:'Copy error',open:'Open Athena',stay:'Stay here',opening:'Opening automatically in {n} seconds...',states:{pending:'pending',running:'running',complete:'done',error:'error'},labels:{manifest:'Read release manifest','database-package':'Prepare PostgreSQL','services-package':'Download runtime services','frontend-package':'Prepare interface',configuration:'Generate configuration',database:'Start PostgreSQL','agent-runtime':'Start Agent Runtime','agent-runtime-client':'Start Runtime Client',frontend:'Start Athena interface'}};
const updateText=zh?{kicker:'服务更新',title:'发现新的服务包',checking:'正在检查本地与远程 Hash...',applying:'正在停止旧服务并安装更新...',apply:'立即更新并重启',later:'暂不更新',hash:'本地 {current} → 远程 {remote}'}:{kicker:'Package update',title:'New service packages are available',checking:'Comparing local and remote package hashes...',applying:'Stopping old services and applying updates...',apply:'Update and restart',later:'Not now',hash:'Local {current} → remote {remote}'};
document.documentElement.lang=zh?'zh-CN':'en';document.getElementById('headline').textContent=text.headline;document.getElementById('message').textContent=text.starting;document.getElementById('steps-title').textContent=text.steps.toUpperCase();document.getElementById('logs-title').textContent=text.logs.toUpperCase();document.getElementById('error-title').textContent=text.errorTitle;document.getElementById('retry').textContent=text.retry;document.getElementById('copy').textContent=text.copy;document.getElementById('open-athena').textContent=text.open;document.getElementById('stay').textContent=text.stay;
let source='launcher',lastState='',redirectTimer=null,stay=false,currentError='';
const esc=value=>String(value??'');
function render(data){document.getElementById('version').textContent='v'+esc(data.version);document.getElementById('message').textContent=esc(data.message)||text.starting;const complete=data.steps.filter(s=>s.status==='complete').length;document.getElementById('count').textContent=complete+' / '+data.steps.length;const active=data.steps.some(s=>s.status==='running') ? 0.35 : 0;document.getElementById('progress').style.width=((complete+active)/data.steps.length*100)+'%';document.getElementById('steps').innerHTML='';for(const step of data.steps){const row=document.createElement('div');row.className='step '+step.status;const symbol=step.status==='complete'?'✓':step.status==='error'?'!':step.status==='running'?'•':'';row.innerHTML='<div class="dot">'+symbol+'</div><div><div class="step-name"></div><div class="step-detail"></div></div><div class="step-state"></div>';row.querySelector('.step-name').textContent=text.labels[step.id]||step.label;row.querySelector('.step-detail').textContent=step.detail||'';row.querySelector('.step-state').textContent=text.states[step.status]||step.status;document.getElementById('steps').appendChild(row)}const pulse=document.getElementById('pulse'),box=document.getElementById('error-box'),ready=document.getElementById('ready-actions');pulse.className='pulse '+data.state;box.classList.toggle('show',data.state==='error');ready.classList.toggle('show',data.state==='ready');if(data.state==='error'){document.getElementById('headline').textContent=text.error;currentError=data.error||data.message;document.getElementById('error-text').textContent=currentError}else if(data.state==='ready'){document.getElementById('headline').textContent=text.ready;document.getElementById('message').textContent=text.readyMsg;if(lastState!=='ready'&&!stay)startRedirect(data.frontendUrl)}else{document.getElementById('headline').textContent=text.headline}lastState=data.state;document.getElementById('open-athena').onclick=()=>{if(data.frontendUrl)location.href=data.frontendUrl}}
const renderStartup=render;let updateWasBlocking=false;render=function(data){const state=data.update?.state||'idle';const blocking=['checking','available','applying','error'].includes(state);window.updateBlocksRedirect=blocking;if(blocking&&redirectTimer){clearInterval(redirectTimer);redirectTimer=null}renderStartup(data);renderUpdate(data.update||{state:'idle'});if(updateWasBlocking&&!blocking&&data.state==='ready'&&!stay)startRedirect(data.frontendUrl);updateWasBlocking=blocking};
function renderUpdate(update){const box=document.getElementById('update-box'),show=['checking','available','applying','error'].includes(update.state);box.classList.toggle('show',show);document.getElementById('update-kicker').textContent=updateText.kicker.toUpperCase();document.getElementById('update-title').textContent=updateText.title;const message=update.state==='checking'?updateText.checking:update.state==='applying'?updateText.applying:(update.message||'');document.getElementById('update-message').textContent=message;const list=document.getElementById('update-list');list.innerHTML='';for(const item of update.components||[]){const node=document.createElement('div');node.className='update-item';const name=document.createElement('div');name.className='update-name';name.textContent=item.displayName;const hash=document.createElement('div');hash.className='update-hash';hash.textContent=updateText.hash.replace('{current}',shortHash(item.currentHash)).replace('{remote}',shortHash(item.remoteHash));node.append(name,hash);list.appendChild(node)}const apply=document.getElementById('update-apply'),dismiss=document.getElementById('update-dismiss');apply.textContent=updateText.apply;dismiss.textContent=updateText.later;apply.disabled=update.state!=='available';dismiss.style.display=update.canDefer?'inline-block':'none'}
function shortHash(value){value=String(value||'').replace(/^2:/,'');return value.length>12?value.slice(0,12):value}
function startRedirect(url){if(!url||window.updateBlocksRedirect)return;let n=5;const note=document.getElementById('ready-note');note.textContent=text.opening.replace('{n}',n);redirectTimer=setInterval(()=>{n--;note.textContent=text.opening.replace('{n}',n);if(n<=0){clearInterval(redirectTimer);location.href=url}},1000)}
async function update(){try{const response=await fetch('/api/status',{cache:'no-store'});render(await response.json())}catch(error){document.getElementById('message').textContent=error.message}}
async function updateLog(){try{const response=await fetch('/api/log?source='+source,{cache:'no-store'});const value=await response.text();const box=document.getElementById('log'),nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<50;box.textContent=value||'No log output yet.';if(nearBottom)box.scrollTop=box.scrollHeight}catch(error){}}
document.querySelectorAll('.tab').forEach(tab=>tab.onclick=()=>{document.querySelectorAll('.tab').forEach(item=>item.classList.remove('active'));tab.classList.add('active');source=tab.dataset.log;updateLog()});document.getElementById('retry').onclick=async()=>{const button=document.getElementById('retry');button.disabled=true;button.textContent=text.retrying;try{await fetch('/api/retry',{method:'POST'});await update()}finally{setTimeout(()=>{button.disabled=false;button.textContent=text.retry},1000)}};document.getElementById('update-apply').onclick=async()=>{await fetch('/api/update/apply',{method:'POST'});await update()};document.getElementById('update-dismiss').onclick=async()=>{await fetch('/api/update/dismiss',{method:'POST'});await update()};document.getElementById('copy').onclick=()=>navigator.clipboard?.writeText(currentError);document.getElementById('stay').onclick=()=>{stay=true;if(redirectTimer)clearInterval(redirectTimer);document.getElementById('ready-note').textContent=''};update();updateLog();setInterval(update,700);setInterval(updateLog,1000);
</script>
</body>
</html>`
